const fs = require('fs');
const XLSX = require('xlsx');

// Function to read an single Excel file
function readExcelFile(filePath) {
  const data = fs.readFileSync(filePath);
  const file = XLSX.read(data, { type: 'buffer' });
  const firstSheetName = file.SheetNames[0];
  const firstSheet = file.Sheets[firstSheetName];
  const json = XLSX.utils.sheet_to_json(firstSheet);
  return json;
}

// Function to compare two Excel files
function compareExcelFiles(file1, file2) {
  const data1 = readExcelFile(file1);
  const data2 = readExcelFile(file2);

  const discrepancies = [];

  // Check if the number of rows is the same
  if (data1.length !== data2.length) {
    discrepancies.push(`Number of rows differs: ${data1.length} vs ${data2.length}`);
  }

  // Compare each row
  for (let i = 0; i < data1.length; i++) {
    const row1 = data1[i];
    const row2 = data2[i];

    // Check if the number of columns is the same
    if (Object.keys(row1).length !== Object.keys(row2).length) {
      discrepancies.push(`Number of columns differs at row ${i}: ${Object.keys(row1).length} vs ${Object.keys(row2).length}`);
