    // Compare each cell
    for (const key of Object.keys(row1)) {
      if (row1[key] !== row2[key]) {
        discrepancies.push(`Discrepancy at row ${i}, column ${key}: ${row1[key]} vs ${row2[key]}`);
      }
    }
  }

  return discrepancies;
}

